import{_ as r,o as a,c as i,aQ as l}from"./chunks/framework.C8WmN7-d.js";const u=JSON.parse('{"title":"WordPress 插件","description":"","frontmatter":{},"headers":[],"relativePath":"dev/php/wordpress/plugin/index.md","filePath":"dev/php/wordpress/plugin/index.md","lastUpdated":1773052438000}'),o={name:"dev/php/wordpress/plugin/index.md"};function t(s,e,n,d,p,m){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="wordpress-插件" tabindex="-1">WordPress 插件 <a class="header-anchor" href="#wordpress-插件" aria-label="Permalink to &quot;WordPress 插件&quot;">​</a></h1><p>WordPress 插件用于扩展站点功能，可从后台安装官方/第三方插件，或自行开发。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ul><li><strong>后台安装</strong>：登录管理后台 → 「插件」→「安装插件」，搜索后点击「现在安装」并启用。</li><li><strong>上传安装</strong>：若为 zip 包，在「安装插件」页选择「上传插件」并选择文件安装。</li><li><strong>手动安装</strong>：将插件目录放到 <code>wp-content/plugins/</code> 下，在后台「插件」页启用。</li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li><a href="https://developer.wordpress.org/plugins/" target="_blank" rel="noreferrer">WordPress 插件手册（开发）</a></li><li><a href="https://developer.wordpress.org/plugins/plugin-basics/" target="_blank" rel="noreferrer">插件 API 参考</a></li><li><a href="https://wordpress.org/plugins/" target="_blank" rel="noreferrer">WordPress 插件目录</a></li></ul><hr><h2 id="常用插件示例" tabindex="-1">常用插件示例 <a class="header-anchor" href="#常用插件示例" aria-label="Permalink to &quot;常用插件示例&quot;">​</a></h2><h3 id="all-in-one-wp-migration-unlimi" tabindex="-1">All-in-One WP Migration Unlimi <a class="header-anchor" href="#all-in-one-wp-migration-unlimi" aria-label="Permalink to &quot;All-in-One WP Migration Unlimi&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>更推荐使用宝塔面板部署后，使用宝塔的备份和恢复来实现项目迁移。</p></div><h3 id="pdf-embedder-premium" tabindex="-1">PDF Embedder Premium <a class="header-anchor" href="#pdf-embedder-premium" aria-label="Permalink to &quot;PDF Embedder Premium&quot;">​</a></h3><p>在文章或页面中直接嵌入、展示 PDF，访客可在站内浏览而无需跳转下载。</p><p><strong>用途简述</strong></p><ul><li>在正文中像插入图片一样嵌入 PDF，支持响应式与全屏、连续滚动。</li><li>Premium 支持：禁止下载/打印、超链接、页码、全屏、下载与浏览统计，可去除品牌标识；可加水印（如用户邮箱）以限制截图传播。</li></ul><p><strong>使用步骤</strong></p><ol><li>先安装并启用免费版 <a href="https://wordpress.org/plugins/pdf-embedder/" target="_blank" rel="noreferrer">PDF Embedder</a>（Premium 依赖该基础插件）。</li><li>编辑文章或页面 → 「添加媒体」→ 上传 PDF 到媒体库，选择后插入。会生成短代码：<code>[pdf-embedder url=&#39;...&#39;]</code>，也可在编辑器中直接使用该短代码。</li><li>在「设置」→「PDF Embedder」中配置宽度、工具栏位置、是否允许下载/打印等；Premium 需在插件设置中填写许可证密钥以激活高级功能。</li></ol>',16)])])}const c=r(o,[["render",t]]);export{u as __pageData,c as default};
